import{z as o,x as s,o as l,c as d,q as B,j as A,D as e,d as t,s as i,S as n,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"分布式 KV 与迁移","description":"","frontmatter":{"title":"分布式 KV 与迁移","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-distributed-migration.md","filePath":"llm/kv-distributed-migration.md","lastUpdated":1791413859000}'),p={name:"llm/kv-distributed-migration.md"};function m(D,E,h,C,f,F){const r=s("Mermaid");return l(),d("div",null,[E[2]||(E[2]=B('<h1 id="分布式-kv-与迁移" tabindex="-1">分布式 KV 与迁移 <a class="header-anchor" href="#分布式-kv-与迁移" aria-label="Permalink to &quot;分布式 KV 与迁移&quot;">​</a></h1><div class="epigraph"><p>迁移的幸运在于 KV 只追加不改写：已写的历史天生是只读快照，要协调的只有正在生长的尾部。</p><footer>—— 据 Zhong et al., DistServe, 2024 与 Patel et al., Splitwise, 2023 的分离式服务实践整理</footer></div><p><a href="/llm/kv-speculative-interaction">上一课</a>管住了一台副本内的写入与回滚。集群把问题放大一个维度：<a href="/llm/pd-disaggregation">PD 分离</a>要求预填实例把 KV 交给解码实例；<a href="/llm/scale-down-kv">缩容</a>要求正在生成的请求换地方；<a href="/llm/kv-prefix-cache">前缀缓存</a>想被路由送到对的副本。传输与带宽的账已各自写过，本课写迁移的一致性：迁移期间谁在写、块表怎么重定向、失败算谁的。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>迁移撕开了第一课的所有权：一页两个候选主人。三件事会出错。<strong>双写</strong>：源端继续 decode 追加，目标端也开始写，同一逻辑位置的键出现两个版本。<strong>丢失</strong>：源端在确认送达前释放了页，传输失败后这条请求既不能续算也无处重算。<strong>分裂</strong>：引用计数两半——前缀页在源端被别的请求共享着，迁移请求的那份引用挂到对端后，谁负责这页的生死？叠加的约束是时间：迁移期间请求的 decode 要不要停？停，是用户可见的停顿；不停，就要回答双写。</p><p><span class="marginnote">直觉类比：迁移像给一本正在记账的账本换柜子——两个人同时往同一页记账（双写）、旧账本提前烧了新账本还没送到（丢失）、其中一页还是全家共用的底账（共享前缀的引用计数）。任何一件出岔子，账就对不上了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>冻结–拷贝–切换</strong>。最简单的正确协议：源端在步边界冻结该请求（停止追加），快照块表，传页，对端按清单重建块表与引用计数，路由切走，源端释放。正确性来自「写权移交是原子的」：任何时刻最多一个写者，世代号（块表版本）保证旧路由的迟到更新被拒。代价是停顿等于传输时间。</p><p><strong>增量迁移</strong>。利用 KV 的追加-only 性质砍停顿：历史页只读，可以先流式传；源端继续 decode，只把新追加的尾部增量传过去，最后在尾部做一次小窗口冻结切换。<a href="/llm/pd-kv-transfer">PD 分离</a>是它的极限情形：预填结束时 KV 定型，源端再无追加，一次传完即切换。增量窗口越小，最后的切换停顿越接近毫秒级。</p><p><strong>失败语义</strong>。切换确认前，源端仍是负责人；超时未确认，就丢弃对端半成品、源端续跑或整体重排（丢 KV 重 prefill）。这条兜底要提前定价：重算成本 = 该请求的 prefill 报价，传输失败的期望损失 = 传输失败率 × 重算成本——值不值得迁移，先过这道算术。路由侧从源头减少迁移：<a href="/llm/kv-aware-routing">缓存感知路由</a>把请求送到已有前缀的副本，<a href="/llm/kv-rdma-fetch">RDMA 拉取</a>把跨机读取做成对端主动取，而不是源端推。</p><p><span class="marginnote">为什么先算失败账：设迁移失败率 1%、重算一条长前缀要 4 秒 GPU 时间，那一万次迁移的期望损失就是约 100 次重算 ≈ 400 GPU 秒——可能比迁移本身省下的时间还多。这道算术不过关，协议再优雅也不该上线。</span></p>',11)),(l(),A(n,null,{default:e(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRIG%5B%22%E8%A7%A6%E5%8F%91%EF%BC%9A%E7%BC%A9%E5%AE%B9%20%2F%20PD%20%E4%BA%A4%E6%8E%A5%20%2F%20%E5%9D%87%E8%A1%A1%22%5D%20--%3E%20FREEZE%5B%22%E6%BA%90%E7%AB%AF%E6%AD%A5%E8%BE%B9%E7%95%8C%E5%86%BB%E7%BB%93%EF%BC%8C%E5%BF%AB%E7%85%A7%E5%9D%97%E8%A1%A8%22%5D%0A%20%20FREEZE%20--%3E%20COLD%5B%22%E5%8E%86%E5%8F%B2%E5%8F%AA%E8%AF%BB%E9%A1%B5%E6%B5%81%E5%BC%8F%E4%BC%A0%E8%BE%93%22%5D%0A%20%20COLD%20--%3E%20TAIL%5B%22%E5%B0%BE%E9%83%A8%E5%A2%9E%E9%87%8F%20%2B%20%E5%B0%8F%E7%AA%97%E5%8F%A3%E5%86%BB%E7%BB%93%22%5D%0A%20%20TAIL%20--%3E%20REB%5B%22%E5%AF%B9%E7%AB%AF%E9%87%8D%E5%BB%BA%E5%9D%97%E8%A1%A8%E4%B8%8E%E5%BC%95%E7%94%A8%E8%AE%A1%E6%95%B0%22%5D%0A%20%20REB%20--%3E%20ACK%7B%22%E7%A1%AE%E8%AE%A4%E9%80%81%E8%BE%BE%3F%22%7D%0A%20%20ACK%20--%3E%7C%E6%98%AF%7C%20CUT%5B%22%E8%B7%AF%E7%94%B1%E5%88%87%E6%8D%A2%EF%BC%8C%E6%BA%90%E7%AB%AF%E9%87%8A%E6%94%BE%22%5D%0A%20%20ACK%20--%3E%7C%E5%90%A6%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%E5%8D%8A%E6%88%90%E5%93%81%EF%BC%9A%E6%BA%90%E7%AB%AF%E7%BB%AD%E8%B7%91%E6%88%96%E9%87%8D%E6%8E%92%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>一致性归根到底还是所有权：迁移协议本质上是把「写权 + 引用」这对状态从源端原子搬到对端，块表世代号是搬运的载体。KV 的追加-only 是这份工作比一般有状态服务友好的根源——历史不可变，传输天然是流式的，需要协商的只有尾部一小段。这也解释了为什么<a href="/llm/kv-tiered-storage">分层存储</a>与迁移能共用一套块接口：换介质、换副本、换机，动的都是「页的住所与主人」，不是页的内容。</p><p><span class="marginnote">术语翻译：世代号（generation）就是块表的「版本号」，每次变更就加一。旧路由拿着第 7 版的地址来写，源端一看现在已是第 8 版，直接拒收——迟到的更新不需要复杂的锁，一次数字比对就挡住了。</span></p><p><span class="marginnote">量级感受：8B 模型 FP16 的 KV 是 128 KiB/token，1K token 历史约 128 MiB，100 Gbps 网线约 10 ms；一条 32K 请求全量约 4 GiB，约三分之一秒。增量迁移把切换停顿压到尾部那一小段——全量传输的账只付给带宽，不付给停顿。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>同构假设很脆：两端 TP 度、精度、块大小不同，就要重切片与重量化，成本从「拷贝」涨成「重算一级」，多数工程选择不迁、改用重排。<a href="/llm/kv-lifecycle-ownership">引用计数</a>跨引擎不可移植，清单在对端重建时要连带前缀共享的间接引用，漏一条就是提前释放。缩容一次性触发大量迁移会形成迁移风暴，挤占与正常 decode 同一张网；分级排水比一步到位稳。最后，KV 是用户数据：跨信任域传输与驻留要走与提示正文同级的隔离与合规，别因为是缓存就绕过。</p>',6)),(l(),A(n,null,{default:e(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E8%A6%81%E8%BF%81%E4%B8%80%E6%9D%A1%20KV%22%5D%20--%3E%20HOMO%7B%22%E4%B8%A4%E7%AB%AF%E5%90%8C%E6%9E%84%E5%90%97%EF%BC%9ATP%20%2F%20%E7%B2%BE%E5%BA%A6%20%2F%20%E5%9D%97%E5%A4%A7%E5%B0%8F%22%7D%0A%20%20HOMO%20--%20%22%E5%90%8C%E6%9E%84%22%20--%3E%20CP%5B%22%E7%BA%AF%E6%8B%B7%E8%B4%9D%EF%BC%9A%E9%A1%B5%E6%8C%89%E5%8E%9F%E6%A0%B7%E6%B5%81%E5%BC%8F%E4%BC%A0%22%5D%0A%20%20HOMO%20--%20%22%E5%BC%82%E6%9E%84%22%20--%3E%20RS%5B%22%E9%87%8D%E5%88%87%E7%89%87%20%2B%20%E9%87%8D%E9%87%8F%E5%8C%96%22%5D%0A%20%20RS%20--%3E%20RE%5B%22%E6%88%90%E6%9C%AC%E4%BB%8E%E6%8B%B7%E8%B4%9D%E6%B6%A8%E6%88%90%E9%87%8D%E7%AE%97%E4%B8%80%E7%BA%A7%22%5D%0A%20%20RE%20--%3E%20ALT%5B%22%E5%B7%A5%E7%A8%8B%E4%B8%8A%E5%A4%9A%E6%94%B9%E8%B5%B0%E9%87%8D%E6%8E%92%EF%BC%9A%E4%B8%A2%20KV%20%E9%87%8D%20prefill%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[5]||(E[5]=a("ul",null,[a("li",null,"迁移协调的是「写权 + 引用」的原子移交；追加-only 让历史传输天然流式。"),a("li",null,"冻结–拷贝–切换最简单正确；增量迁移把停顿压到尾部小窗口。"),a("li",null,"失败兜底定价：重算成本 × 失败率是迁移可行性的第一道算术。"),a("li",null,"路由与拉取从源头减少迁移；同构（TP/精度/块大小）是便宜迁移的前提。"),a("li",null,"KV 是用户数据，跨域驻留按提示正文的合规级别处理。"),a("li",null,"出处：Zhong et al., DistServe, 2024；Patel et al., Splitwise, 2023；存储层次据本仓库分层 KV、PD 传输课。")],-1))])}const u=o(p,[["render",m]]);export{g as __pageData,u as default};
